@import url("https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,500&family=Inter:wght@400;500;600;700&display=swap");
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.sl-login {
  --ink: #2F323B;
  --ink-soft: #353842;
  --paper: #FEFEFE;
  --card: #FFFFFF;
  --line: #A7CDDE;
  --text: #2F323B;
  --muted: #585A61;
  --gold: #2972A9;
  --gold-bright: #2E9BCB;
  --gold-soft: rgba(46, 155, 203, 0.12);
  --green: #2972A9;
  --error: #2F4C65;
  display: flex;
  height: 100vh;
  background: var(--paper);
  font-family: "Inter", sans-serif;
  color: var(--text);
}

.login-left {
  width: 44%;
  background: var(--ink);
  color: #FEFEFE;
  padding: 48px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: relative;
  overflow: hidden;
}

.login-left::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(135deg, rgba(46, 155, 203, 0.07) 0 1px, transparent 1px 14px);
  pointer-events: none;
}

.left-brand {
  display: flex;
  align-items: center;
  gap: 14px;
  position: relative;
  z-index: 1;
}

.brand-logo {
  width: 46px;
  height: 46px;
  display: block;
  object-fit: contain;
  border-radius: 12px;
  flex-shrink: 0;
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-family: "Playfair Display", serif;
  font-size: 18px;
  font-weight: 700;
}

.brand-tag {
  font-size: 10px;
  color: var(--gold-bright);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  margin-top: 2px;
}

.left-hero {
  position: relative;
  z-index: 1;
  max-width: 420px;
}

.hero-kicker {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--gold-bright);
}

.hero-title {
  font-family: "Playfair Display", serif;
  font-size: 34px;
  line-height: 1.2;
  font-weight: 700;
  margin: 14px 0 18px;
}

.hero-rule {
  width: 56px;
  height: 2px;
  background: var(--gold);
  margin-bottom: 18px;
}

.hero-sub {
  font-size: 13px;
  line-height: 1.7;
  color: rgba(254, 254, 254, 0.68);
}

.left-meta {
  font-size: 11px;
  color: rgba(254, 254, 254, 0.42);
  letter-spacing: 0.06em;
  position: relative;
  z-index: 1;
}

.login-right {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
}

.login-card {
  width: 400px;
}

.login-brand {
  width: 100%;
  height: 150px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  margin-bottom: 24px;
}

.login-brand img {
  display: block;
  width: 230px;
  height: 158px;
  object-fit: cover;
  object-position: center;
}

.card-kicker {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--gold);
}

.login-title {
  font-family: "Playfair Display", serif;
  font-size: 30px;
  font-weight: 700;
  margin: 10px 0 6px;
}

.login-sub {
  font-size: 13px;
  color: var(--muted);
  margin-bottom: 30px;
}

.field-label {
  display: block;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  margin-bottom: 8px;
}

.input-wrap {
  position: relative;
  margin-bottom: 18px;
}

.input-wrap svg {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 17px;
  height: 17px;
  color: var(--muted);
}

.input-wrap input {
  width: 100%;
  height: 46px;
  padding: 0 14px 0 42px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 10px;
  font-size: 14px;
  font-family: "Inter", sans-serif;
  color: var(--text);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-wrap input:focus {
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(41, 114, 169, 0.14);
}

.btn-primary {
  width: 100%;
  height: 46px;
  margin-top: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: var(--green);
  border: none;
  border-radius: 10px;
  color: #FEFEFE;
  font-size: 14px;
  font-weight: 600;
  font-family: "Inter", sans-serif;
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
}

.btn-primary:hover {
  background: var(--ink);
  transform: translateY(-1px);
}

.btn-primary svg {
  width: 16px;
  height: 16px;
  color: var(--gold-bright);
}

.status-message {
  margin-top: 14px;
  padding: 10px;
  border-radius: 10px;
  text-align: center;
  font-size: 12px;
  display: none;
}

.status-message.show {
  display: block;
}

.status-message.error {
  background: rgba(47, 76, 101, 0.08);
  border: 1px solid rgba(47, 76, 101, 0.3);
  color: var(--error);
}

srcDoc.js:
appsmith.onReady(function () {
  var form = document.getElementById('loginForm');
  var loginBtn = document.getElementById('loginBtn');
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    loginBtn.disabled = true;
    loginBtn.innerHTML = '<span>Autenticando...</span>';
    appsmith.updateModel({
      loginEmail: document.getElementById('email').value
    });
    appsmith.triggerEvent('onLoginSubmit');
    setTimeout(function () {
      loginBtn.disabled = false;
      loginBtn.innerHTML = '<span>Acceder al panel</span>';
    }, 3000);
  });
});

